import React, { useEffect, useState, useRef, useMemo, useCallback } from "react";
import axios from "axios";
import { useNavigate, useSearchParams } from "react-router-dom";
import {
  MapContainer, TileLayer, CircleMarker, Popup, Tooltip, GeoJSON, useMap,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import "./FloodMap.css";

const API_BASE_URL =
  process.env.NODE_ENV === "production"
    ? "https://aiiot-1.onrender.com"
    : "http://localhost:8000";

const DEBUG = true;
const log = (...a) => DEBUG && console.log("%c[FloodMap]", "color:#3b82f6;font-weight:700", ...a);

/* ------------------------------------------------------------------ */
/*  NOMINATIM QUEUE                                                    */
/*  Their usage policy is 1 request/second, absolute max. The old code */
/*  fired one per marker on mount (~3,600 at once) which got the app   */
/*  throttled AND froze the main thread with 3,600 re-renders.         */
/* ------------------------------------------------------------------ */
const geoCache = new Map();
let geoQueue = Promise.resolve();

const reverseGeocode = (lat, lon) => {
  const key = `${lat.toFixed(4)},${lon.toFixed(4)}`;
  if (geoCache.has(key)) return Promise.resolve(geoCache.get(key));

  geoQueue = geoQueue
    .then(() => new Promise((r) => setTimeout(r, 1100)))
    .then(async () => {
      if (geoCache.has(key)) return geoCache.get(key);
      const url = `https://nominatim.openstreetmap.org/reverse?format=json&zoom=16&lat=${lat}&lon=${lon}`;
      const res = await axios.get(url);
      geoCache.set(key, res.data);
      log("geocoded", key, "→", res.data?.display_name?.slice(0, 50));
      return res.data;
    })
    .catch((e) => {
      console.warn("[FloodMap] geocode failed", key, e.message);
      return null;
    });
  return geoQueue;
};

const smartName = (osm) => {
  if (!osm) return "Unnamed area";
  const a = osm.address || {};
  const street = a.road || a.street || a.pedestrian;
  const area = a.neighbourhood || a.suburb || a.village || a.hamlet;
  const town = a.town || a.city || a.county;
  if (street && area) return `${street}, ${area}`;
  if (area && town) return `${area}, ${town}`;
  if (street && town) return `${street}, ${town}`;
  return area || town || (osm.display_name || "").split(",").slice(0, 2).join(", ");
};

/* ------------------------------------------------------------------ */
/*  SEVERITY — now driven by DEPTH ONLY, and by the backend's labels    */
/* ------------------------------------------------------------------ */
const SEVERITY = {
  low:      { color: "#10b981", label: "Low",      icon: "fa-check-circle" },
  moderate: { color: "#f59e0b", label: "Moderate", icon: "fa-exclamation-circle" },
  high:     { color: "#f97316", label: "High",     icon: "fa-exclamation-circle" },
  critical: { color: "#ef4444", label: "Critical", icon: "fa-exclamation-triangle" },
};
const sev = (z) => SEVERITY[z.severity] || SEVERITY.low;

/* ------------------------------------------------------------------ */
/*  POPUP — content only mounts when the popup is actually opened      */
/* ------------------------------------------------------------------ */
const ZonePopup = ({ zone }) => {
  const [osm, setOsm] = useState(null);
  const [state, setState] = useState("loading");
  const s = sev(zone);

  useEffect(() => {
    let alive = true;
    reverseGeocode(zone.lat, zone.lon).then((d) => {
      if (!alive) return;
      setOsm(d);
      setState(d ? "ok" : "error");
    });
    return () => { alive = false; };
  }, [zone.lat, zone.lon]);

  return (
    <div className="fm-popup">
      <div className="fm-popup-tag" style={{ color: s.color }}>
        {s.label} risk
      </div>
      <strong className="fm-popup-title">
        {state === "loading" ? "Locating…" : smartName(osm)}
      </strong>

      <div className="fm-popup-metrics">
        <div><span>Mean depth</span><b style={{ color: s.color }}>{zone.depth} m</b></div>
        <div><span>Max depth</span><b style={{ color: s.color }}>{zone.max_depth} m</b></div>
        <div><span>Area</span><b>{zone.area_km2} km²</b></div>
      </div>

      <p className="fm-popup-expl">{zone.explanation}</p>
      {state === "ok" && (
        <div className="fm-popup-addr">
          <i className="fas fa-map-marker-alt" /> {osm.display_name}
        </div>
      )}
    </div>
  );
};

const MapController = ({ target }) => {
  const map = useMap();
  useEffect(() => { if (target) map.flyTo(target, 15, { duration: 1.2 }); }, [target, map]);
  return null;
};

const MapControls = ({ onSearch, onFindMe }) => {
  const [q, setQ] = useState("");
  const [busy, setBusy] = useState(false);
  const submit = async (e) => {
    e.preventDefault();
    if (!q.trim()) return;
    setBusy(true);
    try {
      const r = await axios.get(
        `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`
      );
      if (r.data?.length) onSearch([+r.data[0].lat, +r.data[0].lon]);
      else log("search: no result for", q);
    } catch (e) { console.error("[FloodMap] search failed", e); }
    finally { setBusy(false); }
  };
  return (
    <div className="fm-controls">
      <form onSubmit={submit} className="fm-search">
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search location…" />
        <button type="submit">
          <i className={busy ? "fas fa-circle-notch fa-spin" : "fas fa-search"} />
        </button>
      </form>
      <button onClick={onFindMe} className="fm-locate" title="My location">
        <i className="fas fa-location-arrow" />
      </button>
    </div>
  );
};

/* ------------------------------------------------------------------ */
/*  MAIN                                                               */
/* ------------------------------------------------------------------ */
const FloodMap = () => {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const level = params.get("level");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [center, setCenter] = useState(null);
  const [userPos, setUserPos] = useState(null);
  const [selected, setSelected] = useState(null);

  useEffect(() => {
    let alive = true;
    (async () => {
      const t0 = performance.now();
      console.group("%c[FloodMap] fetch flood-analysis", "color:#3b82f6");
      try {
        setLoading(true);
        setError(null);
        const url = `${API_BASE_URL}/api/weather/flood-analysis`;
        log("GET", url, { level });
        const res = await axios.get(url, { params: { level } });
        if (!alive) return;

        const d = res.data;
        console.table({
          status: d.status,
          source: d.source,
          stage_m: d.current_water_level,
          water_surface_msl: d.water_surface_msl,
          flooded_px: d.flooded_pixels,
          area_km2: d.flooded_area_km2,
          zones: d.zones?.length ?? 0,
          polygons: d.extent?.features?.length ?? 0,
        });
        if (d.severity_summary) console.table(d.severity_summary);
        log(`round trip ${(performance.now() - t0).toFixed(0)} ms`);
        setData(d);
      } catch (e) {
        console.error("[FloodMap] request failed", e?.response?.status, e.message);
        if (alive) setError(e?.response?.data?.message || e.message);
      } finally {
        console.groupEnd();
        if (alive) setLoading(false);
      }
    })();
    return () => { alive = false; };
  }, [level]);

  const zones = useMemo(() => data?.zones ?? [], [data]);
  const stage = data?.current_water_level ?? 0;

  /* radius scales with flooded area so big zones read as big */
  const radiusFor = useCallback((z) => {
    const r = 6 + Math.sqrt(z.pixels || 1) * 1.6;
    return Math.min(26, Math.max(7, r));
  }, []);

  const alert = stage < 3
    ? { t: "Conditions normal", m: "Levels within safe limits.", c: "#10b981", i: "fa-check-circle" }
    : stage < 8
    ? { t: "Caution: rising water", m: "Monitoring required.", c: "#f59e0b", i: "fa-exclamation-circle" }
    : { t: "Flood warning", m: "Extreme risk detected.", c: "#ef4444", i: "fa-exclamation-triangle" };

  if (loading)
    return <div className="fm-loading"><div className="fm-spinner" /><p>Running hydrological model…</p></div>;

  return (
    <div className="fm-page">
      <header className="fm-nav">
        <div className="fm-brand" onClick={() => navigate("/river-forecast")}>
          <i className="fas fa-satellite-dish" /> <span>Periyar Risk</span>
        </div>
        <button onClick={() => navigate("/river-forecast")} className="fm-nav-btn">
          <i className="fas fa-th-large" /> Dashboard
        </button>
      </header>

      {/* ---- COMPACT STATUS STRIP (replaces the 65vh hero) ---- */}
      <div className="fm-strip">
        <div className="fm-strip-main">
          <i className="fas fa-water" />
          <div>
            <span>Current river level</span>
            <b>{stage} m</b>
          </div>
        </div>
        <div className="fm-strip-stats">
          <div><span>Zones at risk</span><b>{zones.length}</b></div>
          <div><span>Flooded area</span><b>{data?.flooded_area_km2 ?? 0} km²</b></div>
          <div><span>Source</span><b>{data?.source === "s3-live" ? "Live sensor" : "Simulated"}</b></div>
        </div>
        <div className="fm-strip-alert" style={{ borderColor: alert.c, color: alert.c }}>
          <i className={`fas ${alert.i}`} />
          <div><h4>{alert.t}</h4><p>{alert.m}</p></div>
        </div>
      </div>

      {error && <div className="fm-error">Backend error: {error}</div>}

      {/* ---- MAP ---- */}
      <section className="fm-map">
        <MapControls onSearch={setCenter} onFindMe={() => {
          navigator.geolocation?.getCurrentPosition(
            (p) => { const c = [p.coords.latitude, p.coords.longitude]; setUserPos(c); setCenter(c); },
            (e) => console.warn("[FloodMap] geolocation denied", e.message)
          );
        }} />

        <div className="fm-legend">
          <h5>Risk scale</h5>
          {["critical", "high", "moderate", "low"].map((k) => (
            <div key={k}><span style={{ background: SEVERITY[k].color }} /> {SEVERITY[k].label}</div>
          ))}
          <div className="fm-legend-sep"><span className="fm-legend-poly" /> Flood extent</div>
        </div>

        {/* preferCanvas is THE fix for pointer lag: all vectors are drawn
            into one <canvas> instead of thousands of SVG DOM nodes. */}
        <MapContainer
          center={[10.20, 76.40]}
          zoom={13}
          preferCanvas
          style={{ height: "100%", width: "100%" }}
        >
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png"
            attribution="&copy; OpenStreetMap, &copy; CARTO"
          />
          <MapController target={center} />

          {/* the real flood shape — ONE layer, not 3,600 dots */}
          {data?.extent && (
            <GeoJSON
              key={stage}
              data={data.extent}
              style={{ color: "#2563eb", weight: 1, fillColor: "#3b82f6", fillOpacity: 0.35 }}
              interactive={false}
            />
          )}

          {/* aggregated zones — clickable, non-overlapping */}
          {zones.map((z) => {
            const s = sev(z);
            return (
              <CircleMarker
                key={z.id}
                center={[z.lat, z.lon]}
                radius={radiusFor(z)}
                pathOptions={{ color: "#fff", weight: 2, fillColor: s.color, fillOpacity: 0.9 }}
                eventHandlers={{ click: () => { setSelected(z.id); log("zone clicked", z); } }}
              >
                <Tooltip direction="top" offset={[0, -4]} opacity={1}>
                  <b style={{ color: s.color }}>{z.max_depth} m</b> · {z.area_km2} km²
                </Tooltip>
                <Popup minWidth={250}>
                  <ZonePopup zone={z} />
                </Popup>
              </CircleMarker>
            );
          })}

          {userPos && (
            <CircleMarker center={userPos} radius={8}
              pathOptions={{ color: "#fff", weight: 2, fillColor: "#3b82f6", fillOpacity: 1 }}>
              <Popup>Your location</Popup>
            </CircleMarker>
          )}
        </MapContainer>
      </section>

      {/* ---- ZONE LIST ---- */}
      <main className="fm-content">
        <h3><i className="fas fa-layer-group" /> Affected areas ({zones.length})</h3>
        {zones.length === 0 ? (
          <div className="fm-empty">
            <i className="fas fa-check-circle" />
            <h4>No active flooding</h4>
            <p>River levels are within safe operational limits.</p>
          </div>
        ) : (
          <div className="fm-zone-list">
            {zones.map((z) => {
              const s = sev(z);
              return (
                <button
                  key={z.id}
                  className={`fm-zone-card${selected === z.id ? " is-selected" : ""}`}
                  style={{ borderLeftColor: s.color }}
                  onClick={() => { setCenter([z.lat, z.lon]); setSelected(z.id); }}
                >
                  <span className="fm-zone-icon" style={{ color: s.color }}>
                    <i className={`fas ${s.icon}`} />
                  </span>
                  <span className="fm-zone-body">
                    <ZoneName zone={z} />
                    <small>{s.label} · max {z.max_depth} m · {z.area_km2} km²</small>
                  </span>
                  <i className="fas fa-crosshairs fm-zone-go" />
                </button>
              );
            })}
          </div>
        )}
      </main>

      <footer className="fm-footer">
        © {new Date().getFullYear()} Center for AI-IoT Innovations
      </footer>
    </div>
  );
};

/* lazily geocoded name for the list, using the same 1 req/s queue */
const ZoneName = ({ zone }) => {
  const [name, setName] = useState(null);
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) {
        io.disconnect();
        reverseGeocode(zone.lat, zone.lon).then((d) => setName(smartName(d)));
      }
    });
    io.observe(el);
    return () => io.disconnect();
  }, [zone.lat, zone.lon]);
  return <strong ref={ref}>{name || `${zone.lat.toFixed(4)}, ${zone.lon.toFixed(4)}`}</strong>;
};

export default FloodMap;
